export PANEX_PATH=/usr/local/bin/PanExplorer_workflow;

#if str($mode.mode) == "accessions":
	    perl ${__tool_directory__}/generateConfig.pl 'None' '$input' config.yaml 'None';
#else if str($mode.mode) == "genbanks":
	    perl ${__tool_directory__}/generateConfig.pl '$private_genomes' 'None' config.yaml 'None';
#else if str($mode.mode) == "fasta":
            perl ${__tool_directory__}/generateConfig.pl '$private_genomes' 'None' config.yaml '$private_genomes_fasta';
#end if

cat config.yaml >$logfile;

touch $vcf;
touch $vntr_matrix;
touch $gfa_file;
touch $coregenes_alignment;

#if $software=="pgap"
    snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_PGAP_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="roary"
#else if $software=="roary" and $generate_core_genes_alignment=="true"
    snakemake --cores 1 --config identity=$min_identity generate_core_genes_alignment=True -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_roary_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="roary"
    snakemake --cores 1 --config identity=$min_identity generate_core_genes_alignment=False -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_roary_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="orthofinder"
    snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_orthofinder_heatmap_upset >>$logfile 2>&1;
#else if $software=="cactus"
    snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_cactus_heatmap_upset_COG2 >>$logfile 2>&1;
#else if $software=="pggb"
    snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_pggb_heatmap_upset_COG >>$logfile 2>&1;
#else
    snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_panacota_heatmap_upset_COG >>$logfile 2>&1;
#end if

echo "" > files.txt;
#for $i, $s in enumerate($inputs)
    ln -s '${s}' genome${i}.fasta;
    echo genome${i}.fasta >> files.txt;
#end for

raptor build files.text
    #if $window$ --window ${window} #end if#
    --threads ${threads}
    --parts ${parts}
    --kmer ${kmer}
    --size ${size}
    --hash ${hash}
    ${compressed}
    ${compute_minimiser}
    ${disable_cutoffs}
    --output output.index;


  #import imp
  #set $runIdentifier=str($outputData).rsplit("/")[-1].rsplit(".")[0]
  #set $general_functions=$imp.load_source('General_functions', $__tool_directory__+'/../../src/General_functions.py')
  ##change for Planemo test
  ##set $general_functions=$imp.load_source('General_functions', $__tool_directory__+'/src/General_functions.py')
  #set $ret_code=$general_functions.selectSubSetTable($inputSection['inputData'].file_name,$inputSection['headerNumber'].value,[0],$volcanoSection['volcanoList'],$__new_file_path__+'/'+$__user_id__+'_'+$runIdentifier+'_statisticsFormated.csv',$log.file_name)

  if [ $ret_code != 0 ]; then
    printf "[ERROR]Error during formated statistics file generation\n" >> $log;
    exit $ret_code;
  fi; 

  mv ${__new_file_path__}/${__user_id__}_${runIdentifier}_statisticsFormated.csv ./statisticsFormated.csv;

  #for $i, $s in enumerate( $volcanoSection.volcanoList )
  #if $s.volcanoName!='':
    printf "\$(($i+1))\t${s.volcanoName}\n" >> ./correspondanceVolcanoNames.csv;
  #else:
    printf "\$(($i+1))\t\$(($i+1))_${s.pvalColumn}\n" >> ./correspondanceVolcanoNames.csv;
  #end if
  #end for


  Rscript '$__tool_directory__/../../src/VolcanoPlotsScript.R' -i 'statisticsFormated.csv' -l '$log' -o '$outputData' -f 'pdf'
  ##change for Planemo test
  ##Rscript '$__tool_directory__/src/VolcanoPlotsScript.R' -i 'statisticsFormated.csv' -l '$log' -o '$outputData' -f 'pdf'
    #for $i, $s in enumerate( $volcanoSection.volcanoList )
      -n '${s.volcanoName}'
      -p '${s.pvalColumn}'
      -c '${s.fcColumn}'
      -m '${s.fdrColumn}'
    #end for
      -d '$plotSection.fcKind'
      -s $plotSection.FDRthreshold
      -e $plotSection.FCthreshold
    #if $plotSection.geneInformation.addGeneInfo:
      -x '$plotSection.geneInformation.organismID'
      -y '$plotSection.geneInformation.infoInRowType'
    #end if
  ;
   ret_code=\$?;
   if [ \$ret_code != 0 ]; then
    exit \$ret_code;
   else
    bash $scriptTransfer;
    ret_code=\$?;
    if [ \$ret_code != 0 ]; then
      exit \$ret_code;
    fi 
   fi;

printf "[INFO]End of tool script" >> $log;
